function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'MaxStack' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with MaxStack and no arguments.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls after the constructor.';
  let live = 0;
  for (let i = 1; i < operations.length; i++) {
    const name = operations[i];
    if (name === 'push') {
      const x = args[i][0];
      if (args[i].length !== 1 || !Number.isInteger(x) || x < -10000000 || x > 10000000) return 'push takes one whole number from -10^7 to 10^7.';
      live++;
      continue;
    }
    if (!['pop', 'top', 'peekMax', 'popMax'].includes(name)) return 'Only push, pop, top, peekMax and popMax can follow the constructor.';
    if (args[i].length !== 0) return `${name} takes no arguments.`;
    if (live === 0) return `${name} needs a non-empty stack.`;
    if (name === 'pop' || name === 'popMax') live--;
  }
  return null;
}

