class MaxStack {
  constructor() {
    this.stack = [];
    this.heap = [];
    this.count = 0;
  }

  push(x) {
    const entry = { value: x, id: this.count++, removed: false };
    this.stack.push(entry);
    this.heap.push(entry);
    this.siftUp(this.heap.length - 1);
  }

  pop() {
    const entry = this.topEntry();
    entry.removed = true;
    return entry.value;
  }

  top() {
    return this.topEntry().value;
  }

  peekMax() {
    return this.maxEntry().value;
  }

  popMax() {
    const entry = this.maxEntry();
    entry.removed = true;
    return entry.value;
  }

  topEntry() {
    while (this.stack[this.stack.length - 1].removed) {
      this.stack.pop();
    }
    return this.stack[this.stack.length - 1];
  }

  maxEntry() {
    while (this.heap[0].removed) {
      const last = this.heap.pop();
      if (this.heap.length > 0) {
        this.heap[0] = last;
        this.siftDown(0);
      }
    }
    return this.heap[0];
  }

  higher(a, b) {
    return a.value > b.value || (a.value === b.value && a.id > b.id);
  }

  siftUp(index) {
    const heap = this.heap;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (!this.higher(heap[index], heap[parent])) break;
      [heap[parent], heap[index]] = [heap[index], heap[parent]];
      index = parent;
    }
  }

  siftDown(index) {
    const heap = this.heap;
    for (;;) {
      const left = 2 * index + 1;
      const right = left + 1;
      let best = index;
      if (left < heap.length && this.higher(heap[left], heap[best])) best = left;
      if (right < heap.length && this.higher(heap[right], heap[best])) best = right;
      if (best === index) return;
      [heap[best], heap[index]] = [heap[index], heap[best]];
      index = best;
    }
  }
}

