class MaxStack {
  // A plain array: scan for the maximum each time and splice out its last copy.
  constructor() {
    this.items = [];
  }
  push(x) {
    this.items.push(x);
  }
  pop() {
    return this.items.pop();
  }
  top() {
    return this.items[this.items.length - 1];
  }
  peekMax() {
    return Math.max(...this.items);
  }
  popMax() {
    const best = Math.max(...this.items);
    this.items.splice(this.items.lastIndexOf(best), 1);
    return best;
  }
}

