function generate(rand, size) {
  const operations = ['MaxStack'];
  const args = [[]];
  const calls = size === 'large' ? 499 : 1 + Math.floor(rand() * 14);
  // A narrow value range makes equal maxima, and so the top-most rule, common.
  const span = size === 'large' ? (rand() < 0.5 ? 10000000 : 50) : (rand() < 0.2 ? 10000000 : 3);
  const pushRate = 0.35 + rand() * 0.4;
  let live = 0;
  for (let i = 0; i < calls; i++) {
    if (live === 0 || rand() < pushRate) {
      operations.push('push');
      args.push([Math.floor(rand() * (2 * span + 1)) - span]);
      live++;
    } else {
      const operation = ['pop', 'top', 'peekMax', 'popMax'][Math.floor(rand() * 4)];
      operations.push(operation);
      args.push([]);
      if (operation === 'pop' || operation === 'popMax') live--;
    }
  }
  return [operations, args];
}
